contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "not enough balance for funding");
        uint beforeBalance = address(c).balance;
        c.sendMoney(target, amount); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;
        assert(afterBalance == beforeBalance || afterBalance == beforeBalance - amount);
    }

    receive() external payable {}
}

